package com.joysistvi.CyberAccess.controller;
import com.joysistvi.CyberAccess.model.DrinkItem; import com.joysistvi.CyberAccess.service.DrinkServiceImpl; import java.sql.SQLException; import java.util.List;
public class DrinkController {private final DrinkServiceImpl service;public DrinkController(){this(new DrinkServiceImpl());}public DrinkController(DrinkServiceImpl s){service=s;}public List<DrinkItem> getAll()throws SQLException{return service.getAll();}public List<DrinkItem> getByCategory(int id)throws SQLException{return service.getByCategory(id);}public DrinkItem getById(int id)throws SQLException{return service.getById(id);}public void add(DrinkItem x)throws SQLException{service.add(x);}public boolean update(DrinkItem x)throws SQLException{return service.update(x);}public boolean delete(int id)throws SQLException{return service.delete(id);}}
